//! Rust side of the OpenRCT2 agent bridge.
//!
//! Linked into the game as a staticlib. The C++ side (src/openrct2/rustbridge/)
//! calls into these `extern "C"` entry points; the header is generated by
//! cbindgen. Keep this boundary thin: raw C types only, all real logic behind
//! it in safe Rust.
//!
//! Host functions (implemented in RustBridge.cpp) are the reverse direction:
//! Rust calling into the game. cbindgen emits declarations for both directions
//! into orct2_agent.h; the extern block in host.rs is the single source of truth.

mod host;
mod library;
mod mcp;
mod montage;
mod pieces;
mod presentation;
mod program;
mod replay;
mod report;
mod similarity;

use std::ffi::CStr;
use std::os::raw::c_char;

use crate::program::ProgramOutcome;

/// Called once at context startup, before any park is loaded.
///
/// Returns 0 on success. Nonzero means the bridge failed to initialise and the
/// game should carry on without it (the eval harness will notice and bail).
#[no_mangle]
pub extern "C" fn orct2_agent_init() -> i32 {
    0
}

/// Called every game tick from the eval loop.
#[no_mangle]
pub extern "C" fn orct2_agent_tick(tick: u32) {
    let _ = tick;
}

/// Reads a JSON track program from `path` and executes it against the live
/// game (create ride, place pieces, flip to testing). Returns an owned outcome
/// handle; pass it to `orct2_agent_eval_finish`, which frees it. Never null.
///
/// # Safety
/// `path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_run_program(path: *const c_char) -> *mut ProgramOutcome {
    let outcome = match read_c_path(path)
        .map(|p| std::fs::read_to_string(&p).map_err(|e| format!("read {p}: {e}")))
    {
        Some(Ok(json)) => program::run(&json),
        Some(Err(message)) => ProgramOutcome::failure(message),
        None => ProgramOutcome::failure("null/invalid program path".into()),
    };
    if let Some(err) = &outcome.error {
        host::log(&format!("orct2-agent: program failed: {}", err.message));
    } else {
        host::log(&format!(
            "orct2-agent: program ok, {} piece(s) placed, cost {}",
            outcome.pieces_placed, outcome.total_cost
        ));
    }
    Box::into_raw(Box::new(outcome))
}

/// Writes the JSON eval report to `out_path` and consumes `outcome` (which may
/// be null when no program ran). Returns 0 on success.
///
/// # Safety
/// `outcome` must be null or a handle from `orct2_agent_run_program`, passed
/// at most once. `out_path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_eval_finish(
    outcome: *mut ProgramOutcome,
    out_path: *const c_char,
) -> i32 {
    // Reclaim ownership of the outcome allocated by orct2_agent_run_program.
    let outcome = if outcome.is_null() {
        None
    } else {
        Some(*unsafe { Box::from_raw(outcome) })
    };

    let only_ride = outcome.as_ref().and_then(|o| o.ride_id);
    let eval_report = report::build(outcome, only_ride, None, None);

    let Some(path) = read_c_path(out_path) else {
        host::log("orct2-agent: no report path given, skipping report");
        return 1;
    };
    let json = match serde_json::to_string_pretty(&eval_report) {
        Ok(j) => j,
        Err(e) => {
            host::log(&format!("orct2-agent: report serialise failed: {e}"));
            return 1;
        }
    };
    if let Err(e) = std::fs::write(&path, json) {
        host::log(&format!("orct2-agent: report write failed ({path}): {e}"));
        return 1;
    }
    host::log(&format!("orct2-agent: report written to {path}"));
    0
}

/// Renders a park screenshot to `path`; `fit_track` crops to the track's
/// bounding box (full map when no track exists). `xray` renders the
/// see-through verification view: terrain and supports hidden so every placed
/// piece is visible (tunnels included). Returns 0 on success.
///
/// # Safety
/// `path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_capture(
    path: *const c_char,
    zoom: i32,
    rotation: u8,
    fit_track: bool,
    xray: bool,
) -> i32 {
    match read_c_path(path) {
        Some(p) if host::capture(&p, zoom, rotation, fit_track, xray) => 0,
        _ => 1,
    }
}

/// Films the park's coaster into `path` as an mp4 (ffmpeg on PATH does the
/// encoding), starting from the train leaving the station and ending at its next
/// departure, which is one whole cycle and so loops. `max_seconds` bounds a ride
/// that never comes back round (a valleyed circuit, or a lap longer than the
/// cap); those clips are excerpts and say so in the sidecar. Ticks the simulation on, so
/// call it after the report and any screenshot. Returns 0 on success.
///
/// This is how a round recorded before replays existed gets one: rerun its
/// track program through `coasterbench-cli eval --replay`.
///
/// # Safety
/// `path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_capture_replay(
    path: *const c_char,
    max_seconds: u32,
    zoom: i32,
) -> i32 {
    let Some(path) = read_c_path(path) else {
        host::log("orct2-agent: no replay path given");
        return 1;
    };
    let Some(ride_id) = subject_ride() else {
        host::log("orct2-agent: no ride to film");
        return 1;
    };
    match replay::film_ride(&path, ride_id, max_seconds, zoom, None) {
        Ok(filmed) => {
            host::log(&format!(
                "orct2-agent: replay written to {path} ({} frames, {}x{} at {}fps, {})",
                filmed.frames,
                filmed.width,
                filmed.height,
                filmed.fps,
                if filmed.looped {
                    "one full cycle, loops"
                } else {
                    "cut at the cap, does not loop"
                }
            ));
            0
        }
        Err(e) => {
            host::log(&format!("orct2-agent: replay failed: {e}"));
            1
        }
    }
}

/// Applies a round's recorded name and colours to the park's subject ride, the
/// same game actions `style_best_ride` runs. `report_path` is a round's
/// report.json (or any JSON holding a `presentation` object).
///
/// A rerun builds from program.json, which carries no colours, so without this
/// every artifact refilmed for a styled round comes out stock gold. Returns 0
/// on success, and on a report with no presentation, which is not an error.
///
/// # Safety
/// `report_path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_apply_presentation(report_path: *const c_char) -> i32 {
    match read_presentation(report_path) {
        Ok(None) => 0,
        Ok(Some(style)) => {
            let Some(ride_id) = subject_ride() else {
                host::log("orct2-agent: no ride to style");
                return 1;
            };
            match style.apply(ride_id) {
                Ok(()) => {
                    host::log(&format!(
                        "orct2-agent: styled ride {ride_id} '{}'",
                        style.name
                    ));
                    0
                }
                Err(e) => {
                    host::log(&format!("orct2-agent: style failed: {e}"));
                    1
                }
            }
        }
        Err(e) => {
            host::log(&format!("orct2-agent: presentation: {e}"));
            1
        }
    }
}

/// Reads a presentation out of the report at `path`; None when the path is null
/// or the report records no styling.
///
/// # Safety
/// `path` must be null or a valid NUL-terminated string.
unsafe fn read_presentation(
    path: *const c_char,
) -> Result<Option<presentation::RidePresentation>, String> {
    let Some(path) = read_c_path(path) else {
        return Ok(None);
    };
    let json = std::fs::read_to_string(&path).map_err(|e| format!("read {path}: {e}"))?;
    presentation::RidePresentation::from_report(&json)
}

/// Films the track program at `program_path` being assembled piece by piece
/// into `path` as an mp4, then holds on the finished coaster. The camera is the
/// finished track's bounding box, the same crop as the round's park.png.
///
/// `report_path` (nullable) supplies the round's colours, so a styled coaster
/// builds in its own colours and the cut to its replay does not change them.
///
/// Destructive: the already-built ride is demolished and rebuilt from the
/// program, so this must run after the report, the save and any replay. The
/// park is left holding the rebuilt ride.
///
/// # Safety
/// `path`, `program_path` and `report_path` must be null or valid
/// NUL-terminated strings.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_capture_build_montage(
    path: *const c_char,
    program_path: *const c_char,
    report_path: *const c_char,
    zoom: i32,
) -> i32 {
    let (Some(path), Some(program_path)) = (read_c_path(path), read_c_path(program_path)) else {
        host::log("orct2-agent: montage needs both an output path and a program");
        return 1;
    };
    let json = match std::fs::read_to_string(&program_path) {
        Ok(json) => json,
        Err(e) => {
            host::log(&format!("orct2-agent: read {program_path}: {e}"));
            return 1;
        }
    };
    let Some(ride_id) = subject_ride() else {
        host::log("orct2-agent: no built ride to refilm as a montage");
        return 1;
    };
    let style = match unsafe { read_presentation(report_path) } {
        Ok(style) => style,
        Err(e) => {
            // Worth a stock-coloured montage rather than no montage at all.
            host::log(&format!("orct2-agent: montage presentation: {e}"));
            None
        }
    };
    match montage::film_build(&path, &json, style.as_ref(), ride_id, zoom) {
        Ok(m) => {
            host::log(&format!(
                "orct2-agent: montage written to {path} ({} frames, {}x{} at {}fps, \
                 {} piece(s) over {} stage(s) at {} per stage{})",
                m.frames,
                m.width,
                m.height,
                m.fps,
                m.pieces_placed(),
                m.segments.first().map_or(0, |s| s.pacing.stages),
                m.segments.first().map_or(0, |s| s.pacing.pieces_per_stage),
                if m.ok { "" } else { ", build incomplete" }
            ));
            0
        }
        Err(e) => {
            host::log(&format!("orct2-agent: montage failed: {e}"));
            1
        }
    }
}

/// Films a whole run into `path`: every round's program built in order, each
/// torn down for the next, ending held on the last. `manifest_path` is a JSON
/// array of `{"program": path, "report": path}`, oldest round first; `report`
/// is optional and supplies that round's colours.
///
/// The camera is the union of every round's footprint, so the frame never moves
/// and a coaster that grew looks like it grew. Expects a park with no track of
/// its own: unlike the single-round montage it builds everything itself.
///
/// # Safety
/// `path` and `manifest_path` must be null or valid NUL-terminated strings.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_capture_evolution(
    path: *const c_char,
    manifest_path: *const c_char,
    lap_path: *const c_char,
    lap_seconds: u32,
    zoom: i32,
) -> i32 {
    let (Some(path), Some(manifest_path)) = (read_c_path(path), read_c_path(manifest_path)) else {
        host::log("orct2-agent: evolution needs both an output path and a manifest");
        return 1;
    };
    let segments = match read_evolution_manifest(&manifest_path) {
        Ok(segments) => segments,
        Err(e) => {
            host::log(&format!("orct2-agent: evolution manifest: {e}"));
            return 1;
        }
    };
    match montage::film_evolution(&path, &segments, zoom) {
        Ok(m) => {
            host::log(&format!(
                "orct2-agent: evolution written to {path} ({} frames, {}x{} at {}fps, \
                 {} round(s), {} piece(s){})",
                m.frames,
                m.width,
                m.height,
                m.fps,
                m.segments.len(),
                m.pieces_placed(),
                if m.ok { "" } else { ", a round built short" }
            ));
            film_evolution_lap(lap_path, &m, lap_seconds, zoom)
        }
        Err(e) => {
            host::log(&format!("orct2-agent: evolution failed: {e}"));
            1
        }
    }
}

/// Films the champion's lap on the evolution's own camera, so the hero can run
/// the two clips back to back without the coaster shifting at the cut. The
/// round's own replay.mp4 is framed to that round alone, which is a different
/// camera from the union of every round.
///
/// # Safety
/// `lap_path` must be null or a valid NUL-terminated string.
unsafe fn film_evolution_lap(
    lap_path: *const c_char,
    montage: &montage::Montage,
    max_seconds: u32,
    zoom: i32,
) -> i32 {
    let Some(lap_path) = read_c_path(lap_path) else {
        return 0;
    };
    let Some(ride_id) = montage.final_ride else {
        host::log("orct2-agent: evolution left no ride to film a lap of");
        return 1;
    };
    match replay::film_ride(&lap_path, ride_id, max_seconds, zoom, Some(montage.camera)) {
        Ok(filmed) => {
            host::log(&format!(
                "orct2-agent: evolution lap written to {lap_path} ({} frames, {}x{}, {})",
                filmed.frames,
                filmed.width,
                filmed.height,
                if filmed.looped {
                    "one full cycle, loops"
                } else {
                    "cut at the cap, does not loop"
                }
            ));
            0
        }
        Err(e) => {
            host::log(&format!("orct2-agent: evolution lap failed: {e}"));
            1
        }
    }
}

/// Films a round's recorded session from `actions_path`, a JSON array of the
/// tool calls the game accepted (`{"op": "new_ride"|"place"|"undo"|"demolish"|
/// "test", ...}`), into `path` as an mp4.
///
/// Where the build montage replays the tidy program a round ended up with, this
/// replays the working: pieces going down one at a time, coming back off, a
/// whole ride demolished and started again. Worth filming only for an agent
/// that builds incrementally.
///
/// Destructive and self-contained: it builds and demolishes everything itself,
/// so it wants a park with no track of its own.
///
/// # Safety
/// `path` and `actions_path` must be null or valid NUL-terminated strings.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_capture_trace(
    path: *const c_char,
    actions_path: *const c_char,
    zoom: i32,
) -> i32 {
    let (Some(path), Some(actions_path)) = (read_c_path(path), read_c_path(actions_path)) else {
        host::log("orct2-agent: trace montage needs both an output path and an action list");
        return 1;
    };
    let actions = match std::fs::read_to_string(&actions_path)
        .map_err(|e| format!("read {actions_path}: {e}"))
        .and_then(|text| {
            serde_json::from_str::<Vec<montage::TraceAction>>(&text)
                .map_err(|e| format!("{actions_path}: {e}"))
        }) {
        Ok(actions) => actions,
        Err(e) => {
            host::log(&format!("orct2-agent: trace actions: {e}"));
            return 1;
        }
    };
    match montage::film_trace(&path, &actions, zoom) {
        Ok(m) => {
            host::log(&format!(
                "orct2-agent: trace montage written to {path} ({} frames, {}x{} at {}fps, \
                 {} placement(s) replayed{})",
                m.frames,
                m.width,
                m.height,
                m.fps,
                m.pieces_placed(),
                if m.ok { "" } else { ", some refused" }
            ));
            0
        }
        Err(e) => {
            host::log(&format!("orct2-agent: trace montage failed: {e}"));
            1
        }
    }
}

/// Reads the evolution manifest: one entry per round, oldest first.
fn read_evolution_manifest(path: &str) -> Result<Vec<montage::Segment>, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
    let entries: Vec<serde_json::Value> =
        serde_json::from_str(&text).map_err(|e| format!("{path} is not a JSON array: {e}"))?;
    entries
        .iter()
        .enumerate()
        .map(|(index, entry)| {
            let program_path = entry
                .get("program")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| format!("round {index} has no program path"))?;
            let program_json = std::fs::read_to_string(program_path)
                .map_err(|e| format!("read {program_path}: {e}"))?;
            // A round with no recorded presentation builds in stock colours,
            // which is what its own artifacts show.
            let style = match entry.get("report").and_then(serde_json::Value::as_str) {
                Some(report_path) => std::fs::read_to_string(report_path)
                    .map_err(|e| format!("read {report_path}: {e}"))
                    .and_then(|json| presentation::RidePresentation::from_report(&json))?,
                None => None,
            };
            Ok(montage::Segment {
                program_json,
                style,
            })
        })
        .collect()
}

/// The ride a batch eval is about: the best-rated coaster in the park, ignoring
/// stalls (which never get ratings). Falls back to the first coaster, so an
/// untested track can still be filmed, which is when the footage explains most.
fn subject_ride() -> Option<u16> {
    let rides: Vec<host::RideStats> = (0..host::ride_count())
        .filter_map(host::ride_stats)
        .filter(|s| !s.is_stall)
        .collect();
    rides
        .iter()
        .filter(|s| s.has_ratings)
        .max_by_key(|s| s.excitement)
        .or_else(|| rides.first())
        .map(|s| s.id)
}

/// Runs the MCP server on bind:port (bind defaults to 127.0.0.1 when null),
/// blocking the game thread. Tool calls execute game actions directly;
/// `finish_and_test` advances the simulation inline. Returns nonzero if the
/// server could not start.
///
/// # Safety
/// `bind` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_serve(
    bind: *const c_char,
    port: u16,
    control_port: u16,
) -> i32 {
    let bind = read_c_path(bind).unwrap_or_else(|| "127.0.0.1".to_string());
    match mcp::serve(&bind, port, control_port) {
        Ok(()) => 0,
        Err(e) => {
            host::log(&format!("orct2-agent: serve failed: {e}"));
            1
        }
    }
}

/// Writes the stock track design library to `out_path` as JSON:
/// [{name, ride_type, piece_count, pieces}], pieces in track-program form.
/// For the eval driver's library mode. Returns 0 on success.
///
/// # Safety
/// `out_path` must be null or a valid NUL-terminated string.
#[no_mangle]
pub unsafe extern "C" fn orct2_agent_dump_library(out_path: *const c_char) -> i32 {
    let Some(path) = read_c_path(out_path) else {
        host::log("orct2-agent: no library dump path given");
        return 1;
    };
    let designs = match library::load() {
        Ok(designs) => designs,
        Err(e) => {
            host::log(&format!("orct2-agent: library dump failed: {e}"));
            return 1;
        }
    };
    let entries: Vec<serde_json::Value> = designs
        .iter()
        .map(|d| {
            serde_json::json!({
                "name": d.name,
                "ride_type": d.ride_type,
                "piece_count": d.pieces.len(),
                "pieces": library::program_pieces(d),
            })
        })
        .collect();
    let json = match serde_json::to_string_pretty(&entries) {
        Ok(j) => j,
        Err(e) => {
            host::log(&format!("orct2-agent: library serialise failed: {e}"));
            return 1;
        }
    };
    if let Err(e) = std::fs::write(&path, json) {
        host::log(&format!("orct2-agent: library write failed ({path}): {e}"));
        return 1;
    }
    host::log(&format!(
        "orct2-agent: {} design(s) written to {path}",
        entries.len()
    ));
    0
}

/// Called by `coasterbench-cli eval` after the tick loop: logs a per-ride summary
/// through the host so results land in the game's console output.
#[no_mangle]
pub extern "C" fn orct2_agent_eval_summary() {
    let mut lines = Vec::new();
    let mut stall_count = 0usize;
    for index in 0..host::ride_count() {
        let Some(stats) = host::ride_stats(index) else {
            continue;
        };
        if stats.is_stall {
            stall_count += 1;
            continue;
        }
        lines.push(format_ride_line(&stats));
    }
    host::log(&format!(
        "orct2-agent: {} ride(s), {} stall(s) in park",
        lines.len(),
        stall_count
    ));
    for line in &lines {
        host::log(line);
    }
}

fn read_c_path(path: *const c_char) -> Option<String> {
    if path.is_null() {
        return None;
    }
    unsafe { CStr::from_ptr(path) }
        .to_str()
        .ok()
        .map(str::to_owned)
}

/// Formats one fixed-point rating (raw 525 -> "5.25").
fn format_rating(raw: i16) -> String {
    format!("{}.{:02}", raw / 100, (raw % 100).unsigned_abs())
}

fn format_ride_line(stats: &host::RideStats) -> String {
    let status = report::status_name(stats.status);
    if stats.has_ratings {
        format!(
            "ride {} (type {}) [{}] excitement={} intensity={} nausea={}",
            stats.id,
            stats.ride_type,
            status,
            format_rating(stats.excitement),
            format_rating(stats.intensity),
            format_rating(stats.nausea),
        )
    } else {
        format!(
            "ride {} (type {}) [{}] ratings not yet calculated",
            stats.id, stats.ride_type, status
        )
    }
}

#[cfg(test)]
mod tests {
    use crate::host::RideStats;
    use crate::*;

    #[test]
    fn init_reports_success() {
        assert_eq!(orct2_agent_init(), 0);
    }

    #[test]
    fn rating_formatting_matches_game_display() {
        assert_eq!(format_rating(525), "5.25");
        assert_eq!(format_rating(7), "0.07");
        assert_eq!(format_rating(1000), "10.00");
        assert_eq!(format_rating(0), "0.00");
    }

    #[test]
    fn ride_line_with_ratings() {
        let stats = RideStats {
            id: 3,
            ride_type: 52,
            status: 2,
            is_stall: false,
            has_ratings: true,
            excitement: 642,
            intensity: 730,
            nausea: 341,
        };
        assert_eq!(
            format_ride_line(&stats),
            "ride 3 (type 52) [testing] excitement=6.42 intensity=7.30 nausea=3.41"
        );
    }

    #[test]
    fn ride_line_without_ratings() {
        let stats = RideStats {
            id: 0,
            ride_type: 1,
            status: 0,
            is_stall: false,
            has_ratings: false,
            excitement: 0,
            intensity: 0,
            nausea: 0,
        };
        assert_eq!(
            format_ride_line(&stats),
            "ride 0 (type 1) [closed] ratings not yet calculated"
        );
    }
}
